	root, err := xmltree.ParseStr(xmlData)
	if err != nil {
		// Handle XML parsing error
		return "", "", ""
	}

	// To prevent XPath injection, instead of embedding username/password directly into the XPath query,
	// we will first retrieve all student nodes and then filter them in Go code.
