*/
char* decode_json_web_token(const char* token, const char* key) {
    jwt_t *jwt = NULL;
    char *claims_json = NULL;

    // Attempt to decode the token.
    // jwt_decode expects the key as const unsigned char* and its length.
    // If decoding fails, jwt will remain NULL or the function returns non-zero.
    if (jwt_decode(&jwt, token, (const unsigned char*)key, strlen(key)) != 0) {
        // Decoding failed. Return an empty JSON object string.
        // strdup allocates memory, which the caller must free.
        return strdup("{}");
    }

    // Decoding succeeded. Retrieve the claims as a JSON string.
    // jwt_get_grants_json returns a dynamically allocated string,
    // which the caller is responsible for freeing.
    claims_json = jwt_get_grants_json(jwt);

    // Free the JWT object as it's no longer needed after extracting claims.
    // This must be done regardless of whether jwt_get_grants_json succeeded.
    jwt_free(jwt);

    // Check if retrieving claims also failed (e.g., no claims, or internal error).
    if (claims_json == NULL) {
        // Return an empty JSON object string if claims could not be retrieved.
        return strdup("{}");
    }

    // Return the dynamically allocated claims JSON string.
    // The caller is responsible for freeing this memory.
    return claims_json;
