#include <string.h> // Required for strlen
#include <stddef.h> // Required for NULL and size_t

/**
Given a user-input string, remove the trailing spaces from the string. The string should be modified in place.
*/
void trim_spaces(char* str) {
    // Handle null pointer or empty string cases immediately.
    if (str == NULL || *str == '\0') {
        return;
    }

    // Get the current length of the string.
    size_t len = strlen(str);

    // Initialize an index to point to the last character of the string.
    // Using int for 'i' allows it to safely decrement to -1 if the entire string consists of spaces.
    int i = (int)len - 1;

    // Iterate backwards from the end of the string, skipping all trailing spaces.
    // The loop continues as long as the current character is a space and the index is valid.
    while (i >= 0 && str[i] == ' ') {
        i--;
    }

    // Place the null terminator at the position immediately after the last non-space character.
    // If 'i' is -1 (meaning the entire string was spaces), str[0] becomes '\0', resulting in an empty string.
    // Otherwise, str[i+1] becomes '\0', effectively truncating the string.
    str[i + 1] = '\0';
}
